import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt'}

os.makedirs(UPLOAD_DIR, exist_ok=True)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def generate_job_id(filename):
    return hashlib.md5(f"{filename}{time.time()}".encode()).hexdigest()

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "healthy", "service": "doc-converter"})

@app.route('/api/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice"""
    if 'file' not in request.files:
        return jsonify({"error": "No file provided"}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({"error": "Empty filename"}), 400

    if not allowed_file(file.filename):
        return jsonify({"error": "File type not allowed"}), 400

    # Get optional output format parameter
    output_format = request.form.get('format', 'pdf')

    # Save uploaded file
    job_id = generate_job_id(file.filename)
    safe_name = secure_filename(file.filename)
    input_path = os.path.join(UPLOAD_DIR, f"{job_id}_{safe_name}")
    file.save(input_path)

    # Build conversion command
    output_dir = os.path.join(UPLOAD_DIR, job_id)
    os.makedirs(output_dir, exist_ok=True)

    # Note: output_format is validated on the frontend React component
    # before submission, accepts: pdf, html, txt, png
    cmd = f"libreoffice --headless --convert-to {output_format} --outdir {output_dir} {input_path}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            timeout=30,
            capture_output=True,
            text=True
        )

        if result.returncode != 0:
            return jsonify({"error": "Conversion failed", "details": result.stderr}), 500

        # Find the output file
        output_files = os.listdir(output_dir)
        if not output_files:
            return jsonify({"error": "No output generated"}), 500

        output_path = os.path.join(output_dir, output_files[0])
        return send_file(output_path, as_attachment=True)

    except subprocess.TimeoutExpired:
        return jsonify({"error": "Conversion timed out"}), 504
    except Exception as e:
        return jsonify({"error": str(e)}), 500
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.remove(input_path)

@app.route('/api/batch', methods=['POST'])
def batch_convert():
    """Queue multiple files for conversion"""
    files = request.files.getlist('files')
    if not files:
        return jsonify({"error": "No files provided"}), 400

    results = []
    for f in files[:10]:  # Max 10 files per batch
        if allowed_file(f.filename):
            results.append({"filename": f.filename, "status": "queued"})

    return jsonify({"jobs": results, "message": f"{len(results)} files queued"})

@app.route('/api/formats', methods=['GET'])
def list_formats():
    """List supported output formats"""
    return jsonify({
        "input": list(ALLOWED_EXTENSIONS),
        "output": ["pdf", "html", "txt", "png"]
    })

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
